//! Authentication of the protected endpoints.

use axum::extract::FromRequestParts;
use axum::http::request::Parts;

use crate::AppState;
use crate::common::error::ApiError;

/// API key authentication: a handler that asks for it only runs with one of the keys in API_KEYS (header
/// X-API-Key). Without API_KEYS, no request is authenticated.
pub struct Authenticated;

impl FromRequestParts<AppState> for Authenticated {
    type Rejection = ApiError;

    async fn from_request_parts(parts: &mut Parts, state: &AppState) -> Result<Self, Self::Rejection> {
        let key = parts.headers.get("x-api-key").and_then(|value| value.to_str().ok()).unwrap_or("");
        if key.is_empty() || !state.settings.api_keys.iter().any(|valid| same(valid, key)) {
            return Err(ApiError::unauthorized());
        }
        Ok(Self)
    }
}

/// Compares in constant time, so the answer time says nothing about the key.
fn same(a: &str, b: &str) -> bool {
    a.len() == b.len() && a.bytes().zip(b.bytes()).fold(0, |difference, (x, y)| difference | (x ^ y)) == 0
}

